package dev.elpsy.ticket;
import dev.elpsy.ticket.admission.*;
import dev.elpsy.ticket.admission.AdmissionService.*;
import dev.elpsy.ticket.catalog.*;
import dev.elpsy.ticket.catalog.Models.*;
import dev.elpsy.ticket.customer.CustomerService;
import dev.elpsy.ticket.customer.CustomerService.Principal;
import dev.elpsy.ticket.orders.*;
import dev.elpsy.ticket.orders.OrderModels.*;
import dev.elpsy.ticket.orders.OrderModels.Order;
import dev.elpsy.ticket.common.ApiErrors.Problem;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.test.web.servlet.MockMvc;
import jakarta.servlet.http.Cookie;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=true","ticket.admission.active=1","ticket.admission.queue=2","ticket.admission.permit-seconds=2","ticket.admission.idle-seconds=5","ticket.admission.wait-seconds=10","ticket.admission.join-rate=600","ticket.admission.place-rate=100","ticket.orders.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class AdmissionIntegrationTest {
 @Autowired AdmissionService admission;@Autowired AdmissionSettings settings;@Autowired OrderService orders;@Autowired PaymentService payments;
 @Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;
 @Autowired ObjectMapper json;@Autowired MockMvc mvc;@Autowired PlatformTransactionManager transactions;
 String manager="queue-manager-"+UUID.randomUUID();
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));assertTrue(settings.namespace().startsWith("encore-demo-"));db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");assertEquals("PONG",redis.getConnectionFactory().getConnection().ping());}
 Principal customer(){var issue=customers.register("q-"+UUID.randomUUID().toString().substring(0,30),"合成排隊",UUID.randomUUID().toString());return customers.authenticate(issue.token()).orElseThrow();}
 UUID ticket(){return ticket(OffsetDateTime.now().plusHours(1),true);}
 UUID ticket(OffsetDateTime end,boolean publish){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"queue-"+UUID.randomUUID(),"等候室演出","隔離合成","合成場地"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成場次",end.plusDays(1),OffsetDateTime.now().minusHours(1),end));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,10,2));if(publish)catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);return t.id();}
 State join(Principal c,UUID t){return admission.join(c,t,new Join(UUID.randomUUID()));}
 Place place(UUID t){return new Place(UUID.randomUUID(),t,1,1,1200);}
 void problem(int status,Runnable op){assertEquals(status,assertThrows(Problem.class,op::run).status);}
 void expire(UUID t,Principal c){redis.opsForZSet().add(admission.keys(t).get(1),admission.member(c),0);}
 @Test void publicCheckoutDisclosesWaitingRoomEnabled(){UUID t=ticket();UUID e=db.queryForObject("SELECT s.event_id FROM ticket_type t JOIN event_session s ON s.id=t.session_id WHERE t.id=?",UUID.class,t);assertTrue(catalog.detail(e,true).waitingRoomEnabled());}
 @Test void oneActiveOthersFIFOAndPollingDoesNotRenewPermit(){var a=customer();var b=customer();var c=customer();UUID t=ticket();var first=join(a,t);assertEquals("ADMITTED",first.state());var jb=join(b,t);var jc=join(c,t);assertEquals(1,jb.position());assertEquals(2,jc.position());assertEquals(first.expiresAt(),admission.status(a,t).expiresAt());expire(t,a);var second=admission.status(b,t);assertEquals("ADMITTED",second.state());assertEquals("WAITING",admission.status(c,t).state());}
 @Test void duplicateOriginalJoinKeepsPositionAndDeadline(){var a=customer();var b=customer();UUID t=ticket();join(a,t);var body=new Join(UUID.randomUUID());var q=admission.join(b,t,body);var replay=admission.join(b,t,body);assertEquals(q.position(),replay.position());assertEquals(1,redis.opsForZSet().zCard(admission.keys(t).get(0)));assertEquals("WAITING",replay.state());problem(409,()->join(b,t));}
 @Test void concurrentSameUUIDProducesOneMember()throws Exception {var c=customer();UUID t=ticket();var body=new Join(UUID.randomUUID());try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<State>>();for(int i=0;i<6;i++)calls.add(()->admission.join(c,t,body));Long expiry=null;for(var r:pool.invokeAll(calls)){var s=r.get();assertEquals("ADMITTED",s.state());if(expiry==null)expiry=s.expiresAt();assertEquals(expiry,s.expiresAt());}}assertEquals(1,redis.opsForHash().size(admission.keys(t).get(2)));}
 @Test void queueBoundedWithoutEjectingOriginalMembers(){var a=customer();var b=customer();var c=customer();var d=customer();UUID t=ticket();join(a,t);join(b,t);join(c,t);problem(429,()->join(d,t));assertEquals(2,redis.opsForZSet().zCard(admission.keys(t).get(0)));}
 @Test void pollWithoutJoinDoesNotGrantOrCreateMember(){var c=customer();UUID t=ticket();assertEquals("NOT_JOINED",admission.status(c,t).state());assertEquals(0,redis.opsForHash().size(admission.keys(t).get(2)));problem(409,()->orders.place(c,place(t)));}
 @Test void admissionBelongsToOwnerAndTicket(){var a=customer();var b=customer();UUID t=ticket(),other=ticket();join(a,t);problem(409,()->orders.place(b,place(t)));problem(409,()->orders.place(a,place(other)));assertNotNull(orders.place(a,place(t)));}
 @Test void expiredOriginalJoinNeverRenewsAndExplicitNewJoinGoesToBack(){var a=customer();var b=customer();UUID t=ticket();var original=new Join(UUID.randomUUID());admission.join(a,t,original);join(b,t);expire(t,a);assertEquals("EXPIRED",admission.join(a,t,original).state());var again=join(a,t);assertEquals("WAITING",again.state());assertEquals(1,again.position());assertEquals("ADMITTED",admission.status(b,t).state());}
 @Test void retiredOriginalUUIDCannotReviveAfterExplicitRequeueExpires(){var c=customer();UUID t=ticket();var first=new Join(UUID.randomUUID());admission.join(c,t,first);expire(t,c);var second=new Join(UUID.randomUUID());admission.join(c,t,second);expire(t,c);var old=admission.join(c,t,first);assertEquals("EXPIRED",old.state());assertEquals(first.requestId(),old.requestId());problem(409,()->orders.place(c,place(t)));assertEquals(0,redis.opsForZSet().zCard(admission.keys(t).get(1)));}
 @Test void delayedRetiredUUIDDoesNotReplaceCurrentLiveQualification(){var c=customer();UUID t=ticket();var first=new Join(UUID.randomUUID());admission.join(c,t,first);expire(t,c);var current=join(c,t);assertEquals("EXPIRED",admission.join(c,t,first).state());assertEquals(current.requestId(),admission.status(c,t).requestId());assertEquals(current.expiresAt(),admission.status(c,t).expiresAt());}
 @Test void retiredRequestMemoryBoundNeverEvictsOldUUIDIntoNewAdmission(){var c=customer();UUID t=ticket();var first=new Join(UUID.randomUUID());admission.join(c,t,first);for(int i=0;i<20;i++){expire(t,c);join(c,t);}expire(t,c);problem(429,()->join(c,t));assertEquals("EXPIRED",admission.join(c,t,first).state());}
 @Test void admittedPermitCannotExtendByRepeatedJoin(){var c=customer();UUID t=ticket();var body=new Join(UUID.randomUUID());var first=admission.join(c,t,body);assertEquals(first.expiresAt(),admission.join(c,t,body).expiresAt());expire(t,c);problem(409,()->orders.place(c,place(t)));assertEquals("EXPIRED",admission.join(c,t,body).state());}
 @Test void staleWaitingHeadExpiresBeforeNextCustomerAdmission(){var a=customer();var stale=customer();var live=customer();UUID t=ticket();join(a,t);join(stale,t);join(live,t);expire(t,a);expire(t,stale);assertEquals("ADMITTED",admission.status(live,t).state());assertEquals("EXPIRED",admission.status(stale,t).state());}
 @Test void waitAbsoluteDeadlineCannotExtendWithHeartbeat()throws Exception {var a=customer();var b=customer();UUID t=ticket();join(a,t);join(b,t);String key=admission.keys(t).get(2),member=admission.member(b);var node=json.readTree((String)redis.opsForHash().get(key,member));((com.fasterxml.jackson.databind.node.ObjectNode)node).put("joined",node.get("joined").asLong()-20000);redis.opsForHash().put(key,member,json.writeValueAsString(node));admission.status(b,t);assertEquals("EXPIRED",admission.status(b,t).state());}
 @Test void permitNeverExceedsSalesDeadline(){var c=customer();UUID t=ticket(OffsetDateTime.now().plusSeconds(1),true);var state=join(c,t);assertTrue(state.expiresAt()-state.serverNow()<=1000);}
 @Test void invalidDraftClosedTicketsCannotQueue(){var c=customer();problem(404,()->join(c,UUID.randomUUID()));problem(404,()->join(c,ticket(OffsetDateTime.now().plusHours(1),false)));problem(404,()->join(c,ticket(OffsetDateTime.now().minusSeconds(1),false)));}
 @Test void eligibilityDoesNotSkipPGQuoteStockOrQuota(){var c=customer();UUID t=ticket();join(c,t);problem(409,()->orders.place(c,new Place(UUID.randomUUID(),t,1,1,1)));var o=orders.place(c,place(t));assertNotNull(o);problem(409,()->orders.place(c,new Place(UUID.randomUUID(),t,2,1,2400)));assertEquals(1,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));}
 @Test void originalOrderReplayCancelAndPaymentDoNotRequireRedisState(){var c=customer();UUID t=ticket();join(c,t);var body=place(t);var o=orders.place(c,body);redis.delete(admission.keys(t));assertEquals(o,orders.place(c,body));assertEquals("CANCELLED",orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),1)).status());UUID other=ticket();join(c,other);var pending=orders.place(c,place(other));var started=payments.start(c,pending.id(),new PaymentModels.Pay(UUID.randomUUID(),1,1200,"SUCCESS"));redis.delete(admission.keys(other));assertEquals("PAID",payments.reconcile(c,pending.id(),started.payment().id(),new PaymentModels.Reconcile(UUID.randomUUID())).status());}
 @Test void roomStateLossRejectsDirectBookingAndPollDoesNotRejoin(){var c=customer();UUID t=ticket();join(c,t);redis.delete(admission.keys(t));problem(409,()->orders.place(c,place(t)));assertEquals("NOT_JOINED",admission.status(c,t).state());assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));}
 @Test void wrongRedisTypeFailsClosedWithoutPartialQueueOrStock(){var c=customer();UUID t=ticket();var keys=admission.keys(t);redis.opsForValue().set(keys.get(2),"synthetic wrong type");try{problem(503,()->join(c,t));problem(503,()->orders.place(c,place(t)));assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));assertFalse(redis.hasKey(keys.get(0)));}finally{redis.delete(keys);}}
 @Test void tokenBucketIsPerOwnerAndReturnsRetryAfter(){var a=customer();var b=customer();var strict=new AdmissionService(db,redis,json,new AdmissionSettings(true,settings.namespace()+"-strict",1,2,2,5,10,1,1));strict.limit(a,false);var p=assertThrows(Problem.class,()->strict.limit(a,false));assertEquals(429,p.status);assertTrue(p.retryAfterSeconds>0);assertDoesNotThrow(()->strict.limit(b,false));assertDoesNotThrow(()->strict.limit(a,true));}
 @Test void originalOrderReplayDoesNotConsumeFreshRate(){var c=customer();UUID t=ticket();join(c,t);var body=place(t);var o=orders.place(c,body);String bucket=admission.rateKey(c,true);redis.opsForHash().put(bucket,"tokens","0");redis.opsForHash().put(bucket,"last",Long.toString(System.currentTimeMillis()));assertEquals(o,orders.place(c,body));problem(429,()->orders.place(c,place(t)));}
 @Test void disabledCustomerOrLoggedOutCannotRefreshEligibility(){var c=customer();UUID t=ticket();join(c,t);db.update("UPDATE customer_account SET enabled=false WHERE id=?",c.id());problem(401,()->admission.status(c,t));problem(401,()->orders.place(c,place(t)));db.update("UPDATE customer_account SET enabled=true WHERE id=?",c.id());problem(401,()->admission.status(c,t));var b=customer();db.update("DELETE FROM customer_session WHERE token_hash=?",b.sessionHash());problem(401,()->join(b,t));}
 @Test void expiryCheckedAfterActuallyWaitingForTicketLock()throws Exception {var c=customer();UUID t=ticket();var state=join(c,t);try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,t);var task=pool.submit(()->problem(409,()->orders.place(c,place(t))));boolean waiting=false;for(int i=0;i<60;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%FOR UPDATE OF t%'",Integer.class)>0){waiting=true;break;}try{Thread.sleep(30);}catch(Exception e){throw new AssertionError(e);}}assertTrue(waiting);try{Thread.sleep(Math.max(1,state.expiresAt()-System.currentTimeMillis()+100));}catch(Exception e){throw new AssertionError(e);}s.setRollbackOnly();return task;}).get(3,TimeUnit.SECONDS);}assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));}
 @Test void httpCsrfAndUnknownOwnerFieldsRejected()throws Exception {var issue=customers.register("qw-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());var cookie=new Cookie("TICKET_CUSTOMER_SESSION",issue.token());String path="/api/customer/waiting-room/"+ticket()+"/join";mvc.perform(post(path).cookie(cookie).contentType("application/json").content(json.writeValueAsString(new Join(UUID.randomUUID())))).andExpect(status().isForbidden());var csrf=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var node=json.readTree(csrf.getResponse().getContentAsString());mvc.perform(post(path).cookie(cookie,csrf.getResponse().getCookie("TICKET_CUSTOMER_CSRF")).header(node.get("headerName").asText(),node.get("token").asText()).contentType("application/json").content("{\"requestId\":\""+UUID.randomUUID()+"\",\"customerId\":\"spoof\"}")).andExpect(status().isBadRequest());mvc.perform(get(path.substring(0,path.length()-5))).andExpect(status().isUnauthorized());}
}
